class Solution {
public:
    int mostFrequent(vector<int>& nums, int key) {
        unordered_map<int, int> count;
        int bestVal = 0, maxCnt = 0;
        for (int i = 0; i + 1 < (int)nums.size(); i++) {
            if (nums[i] == key) {
                int target = nums[i + 1];
                count[target]++;
                if (count[target] > maxCnt) {
                    maxCnt = count[target];
                    bestVal = target;
                }
            }
        }
        return bestVal;
    }
};

class Solution {
    public int mostFrequent(int[] nums, int key) {
        Map<Integer, Integer> count = new HashMap<>();
        int bestVal = 0, maxCnt = 0;
        for (int i = 0; i + 1 < nums.length; i++) {
            if (nums[i] == key) {
                int target = nums[i + 1];
                int c = count.getOrDefault(target, 0) + 1;
                count.put(target, c);
                if (c > maxCnt) {
                    maxCnt = c;
                    bestVal = target;
                }
            }
        }
        return bestVal;
    }
}

var mostFrequent = function(nums, key) {
    const count = new Map();
    let bestVal = 0, maxCnt = 0;
    for (let i = 0; i + 1 < nums.length; i++) {
        if (nums[i] === key) {
            const target = nums[i + 1];
            const c = (count.get(target) || 0) + 1;
            count.set(target, c);
            if (c > maxCnt) {
                maxCnt = c;
                bestVal = target;
            }
        }
    }
    return bestVal;
};
